#!/usr/bin/env python3
"""Append a snapshot of Kalshi prices for one NFL team's next game.

Usage:
    python3 snapshot.py BUF

Finds the team's next open game on Kalshi, then records every market in the
moneyline (KXNFLGAME), spread (KXNFLSPREAD) and total (KXNFLTOTAL) events for
that game as one row each in data/snapshots.csv.

Standard library only. Uses Kalshi's public, read-only API (GET requests, no key).
"""

import csv
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation

API_BASE = "https://api.elections.kalshi.com/trade-api/v2"
USER_AGENT = "kalshi-nfl-line-tracker/0.1"
TIMEOUT_SECONDS = 20

# Series ticker -> market_type written to the CSV. Moneyline goes first because
# it is used to find the game; spread and total events share its suffix.
SERIES = [
    ("KXNFLGAME", "moneyline"),
    ("KXNFLSPREAD", "spread"),
    ("KXNFLTOTAL", "total"),
]

# Team codes exactly as Kalshi spells them in tickers (note JAC, LAR, WAS).
TEAM_CODES = {
    "ARI", "ATL", "BAL", "BUF", "CAR", "CHI", "CIN", "CLE",
    "DAL", "DEN", "DET", "GB", "HOU", "IND", "JAC", "KC",
    "LAC", "LAR", "LV", "MIA", "MIN", "NE", "NO", "NYG",
    "NYJ", "PHI", "PIT", "SEA", "SF", "TB", "TEN", "WAS",
}

MONTHS = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DATA_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")
CSV_PATH = os.path.join(DATA_DIR, "snapshots.csv")

FIELDS = [
    "timestamp", "event_ticker", "market_ticker", "market_type", "label",
    "yes_bid", "yes_ask", "last", "volume",
]


class SnapshotError(Exception):
    """A problem that should be reported to the user without a traceback."""


def api_get(path, params):
    """GET a Kalshi API path and return the decoded JSON body."""
    url = API_BASE + path + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(
        url, headers={"User-Agent": USER_AGENT, "Accept": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
            return json.load(resp)
    except urllib.error.HTTPError as e:
        raise SnapshotError("Kalshi API returned HTTP %d for %s" % (e.code, url))
    except urllib.error.URLError as e:
        raise SnapshotError("could not reach Kalshi API (%s)" % e.reason)
    except (OSError, ValueError) as e:
        raise SnapshotError("bad response from Kalshi API for %s (%s)" % (url, e))


def api_get_all(path, params, key):
    """GET every page of a cursor-paginated Kalshi list endpoint."""
    items = []
    params = dict(params, limit=200)
    while True:
        body = api_get(path, params)
        items.extend(body.get(key) or [])
        cursor = body.get("cursor")
        if not cursor:
            return items
        params["cursor"] = cursor


def parse_event_suffix(suffix):
    """Split '26NOV09BUFMIN' into (date, ('BUF', 'MIN')), or None if it doesn't parse."""
    if len(suffix) < 7:
        return None
    yy, mon, dd, teams = suffix[:2], suffix[2:5], suffix[5:7], suffix[7:]
    if mon not in MONTHS or not (yy.isdigit() and dd.isdigit()):
        return None
    try:
        game_date = datetime(2000 + int(yy), MONTHS[mon], int(dd)).date()
    except ValueError:
        return None
    # Team codes are 2 or 3 letters and concatenated (e.g. GBNE, NYJKC).
    for n in (2, 3):
        away, home = teams[:n], teams[n:]
        if away in TEAM_CODES and home in TEAM_CODES:
            return game_date, (away, home)
    return None


def find_next_game(team):
    """Return the event suffix (e.g. '26NOV09BUFMIN') of the team's next open game."""
    events = api_get_all(
        "/events", {"series_ticker": "KXNFLGAME", "status": "open"}, "events"
    )
    today = datetime.now(timezone.utc).date()
    candidates = []
    for event in events:
        ticker = event.get("event_ticker", "")
        series, _, suffix = ticker.partition("-")
        if series != "KXNFLGAME":
            continue
        parsed = parse_event_suffix(suffix)
        if parsed is None:
            continue
        game_date, teams = parsed
        # Game dates in tickers are US dates, so allow one day of slack vs UTC.
        if team in teams and (today - game_date).days <= 1:
            candidates.append((game_date, suffix))
    if not candidates:
        raise SnapshotError("no open Kalshi NFL game found for %s" % team)
    return min(candidates)[1]


def to_cents(market, dollars_field, legacy_field):
    """Convert a Kalshi price to integer cents, or '' if the market has none."""
    value = market.get(dollars_field)
    if value not in (None, ""):
        try:
            return int((Decimal(str(value)) * 100).to_integral_value())
        except InvalidOperation:
            raise SnapshotError(
                "unexpected %s value %r on %s"
                % (dollars_field, value, market.get("ticker"))
            )
    # Older API responses gave integer cents directly.
    value = market.get(legacy_field)
    if isinstance(value, int):
        return value
    return ""


def volume_of(market):
    """Contracts traded. Kalshi reports fractional contracts ("218304.60"),
    so this keeps the API's decimal string rather than rounding it."""
    value = market.get("volume_fp")
    if value not in (None, ""):
        return str(value)
    value = market.get("volume")
    return "" if value is None else str(value)


def build_rows(team, timestamp):
    suffix = find_next_game(team)
    rows = []
    for series, market_type in SERIES:
        event_ticker = "%s-%s" % (series, suffix)
        try:
            markets = api_get_all(
                "/markets", {"event_ticker": event_ticker}, "markets"
            )
        except SnapshotError as e:
            if market_type == "moneyline":
                raise
            print("warning: skipping %s (%s)" % (event_ticker, e), file=sys.stderr)
            continue
        if not markets:
            print("warning: no markets listed for %s" % event_ticker, file=sys.stderr)
            continue
        for m in sorted(markets, key=lambda m: m.get("ticker", "")):
            rows.append({
                "timestamp": timestamp,
                "event_ticker": m.get("event_ticker") or event_ticker,
                "market_ticker": m.get("ticker", ""),
                "market_type": market_type,
                "label": m.get("yes_sub_title") or m.get("title") or "",
                "yes_bid": to_cents(m, "yes_bid_dollars", "yes_bid"),
                "yes_ask": to_cents(m, "yes_ask_dollars", "yes_ask"),
                "last": to_cents(m, "last_price_dollars", "last_price"),
                "volume": volume_of(m),
            })
    if not rows:
        raise SnapshotError("Kalshi returned no markets for %s" % suffix)
    return suffix, rows


def append_rows(rows):
    os.makedirs(DATA_DIR, exist_ok=True)
    new_file = not os.path.exists(CSV_PATH) or os.path.getsize(CSV_PATH) == 0
    with open(CSV_PATH, "a", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        if new_file:
            writer.writeheader()
        writer.writerows(rows)


def main(argv):
    if len(argv) != 2:
        print("usage: python3 snapshot.py TEAM   (e.g. BUF)", file=sys.stderr)
        return 2
    team = argv[1].strip().upper()
    if team not in TEAM_CODES:
        print(
            "error: unknown team code %r. Use one of: %s"
            % (argv[1], ", ".join(sorted(TEAM_CODES))),
            file=sys.stderr,
        )
        return 2

    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        suffix, rows = build_rows(team, timestamp)
    except SnapshotError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1

    append_rows(rows)
    counts = {}
    for row in rows:
        counts[row["market_type"]] = counts.get(row["market_type"], 0) + 1
    summary = ", ".join("%d %s" % (counts.get(t, 0), t) for _, t in SERIES)
    print("%s: wrote %d rows for %s (%s) to %s"
          % (timestamp, len(rows), suffix, summary, os.path.relpath(CSV_PATH)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

