                "market_type": market_type,
                "label": m.get("yes_sub_title") or m.get("title") or "",
                "yes_bid": to_cents(m, "yes_bid_dollars", "yes_bid"),
                "yes_ask": to_cents(m, "yes_ask_dollars", "yes_ask"),
                "last": to_cents(m, "last_price_dollars", "last_price"),
                "volume": volume_of(m),
            })
    if not rows:
        raise SnapshotError("Kalshi returned no markets for %s" % suffix)
    return suffix, rows


def append_rows(rows):
    os.makedirs(DATA_DIR, exist_ok=True)
    new_file = not os.path.exists(CSV_PATH) or os.path.getsize(CSV_PATH) == 0
    with open(CSV_PATH, "a", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        if new_file:
            writer.writeheader()
        writer.writerows(rows)


def main(argv):
    if len(argv) != 2:
        print("usage: python3 snapshot.py TEAM   (e.g. BUF)", file=sys.stderr)
        return 2
    team = argv[1].strip().upper()
    if team not in TEAM_CODES:
        print(
            "error: unknown team code %r. Use one of: %s"
            % (argv[1], ", ".join(sorted(TEAM_CODES))),
            file=sys.stderr,
        )
        return 2

    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        suffix, rows = build_rows(team, timestamp)
    except SnapshotError as e:
        print("error: %s" % e, file=sys.stderr)
        return 1

    append_rows(rows)
    counts = {}
    for row in rows:
        counts[row["market_type"]] = counts.get(row["market_type"], 0) + 1
    summary = ", ".join("%d %s" % (counts.get(t, 0), t) for _, t in SERIES)
    print("%s: wrote %d rows for %s (%s) to %s"
          % (timestamp, len(rows), suffix, summary, os.path.relpath(CSV_PATH)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
